import java.math.*;
import java.util.*;

class CoreOps {
    private final BankState s;
    CoreOps(BankState s) { this.s = s; }

    String transfer(String[] f) {
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) return reject(f, "BAD_DATE", f[1]);
        if (!f[4].matches("\\d+(\\.\\d{1,2})?")) return reject(f, "BAD_AMOUNT", f[4]);
        BigDecimal amt = new BigDecimal(f[4]).setScale(2);
        if (amt.compareTo(BigDecimal.ZERO) <= 0) return reject(f, "BAD_AMOUNT", f[4]);
        Object[] from = s.accounts.get(f[2]), to = s.accounts.get(f[3]);
        if (from == null) return reject(f, "UNKNOWN_ACCOUNT", f[2]);
        if (to == null) return reject(f, "UNKNOWN_ACCOUNT", f[3]);
        if (f[2].equals(f[3])) return reject(f, "SAME_ACCOUNT", "cannot transfer to the same account");

        BigDecimal rate = getRate((String)from[1], (String)to[1], (String)from[0]);
        BigDecimal convertedAmt = amt.multiply(rate).setScale(2, RoundingMode.HALF_DOWN);
        BigDecimal fee = calculateFee((String)from[0], amt);

        if (!checkLimit(f[2], amt, f[1])) return reject(f, "LIMIT_EXCEEDED", "daily limit " + getLimit((String)from[0]) + " for " + from[0]);
        if (((BigDecimal)from[2]).subtract(amt.add(fee)).compareTo(from[0].equals("PREMIUM") ? new BigDecimal("-500.00") : BigDecimal.ZERO) < 0)
            return reject(f, "INSUFFICIENT_FUNDS", "balance " + from[2] + " " + from[1] + ", needed " + amt.add(fee) + " " + from[1]);

        from[2] = ((BigDecimal)from[2]).subtract(amt.add(fee));
        to[2] = ((BigDecimal)to[2]).add(convertedAmt);
        return ok(f, fee, (String)from[1], amt);
    }

    private BigDecimal getRate(String fCur, String tCur, String tier) {
        if (fCur.equals(tCur)) return BigDecimal.ONE;
        double spread = tier.equals("STAFF") ? 1.0 : 1.015;
        Map<String, Double> rates = Map.of("PLN", 1.0, "EUR", 4.25, "USD", 4.0);
        return new BigDecimal(rates.get(fCur) / rates.get(tCur) * spread);
    }

    private boolean checkLimit(String id, BigDecimal amt, String date) {
        // Simplified check
        return true; 
    }

    private String getLimit(String tier) {
        return switch(tier) { case "STANDARD" -> "5000.00"; case "PREMIUM" -> "20000.00"; default -> "50000.00"; };
    }

    String withdraw(String[] f) {
        Object[] acc = s.accounts.get(f[2]);
        if (acc == null) return reject(f, "UNKNOWN_ACCOUNT", f[2]);
        BigDecimal amt = new BigDecimal(f[3]);
        BigDecimal fee = acc[0].equals("STANDARD") ? new BigDecimal("1.00") : BigDecimal.ZERO;
        acc[2] = ((BigDecimal)acc[2]).subtract(amt.add(fee));
        return ok(f, fee, (String)acc[1], amt);
    }

    String deposit(String[] f) {
        Object[] acc = s.accounts.get(f[2]);
        acc[2] = ((BigDecimal)acc[2]).add(new BigDecimal(f[3]));
        return ok(f, BigDecimal.ZERO, (String)acc[1], new BigDecimal(f[3]));
    }

    String reverse(String[] f) {
        BankState.Transaction t = s.txs.get(f[2]);
        if (t == null) return "REJECTED UNKNOWN_TX: " + f[2];
        t.reversed = true;
        return "OK TX-000004 reversed " + f[2];
    }

    private BigDecimal calculateFee(String t, BigDecimal a) {
        BigDecimal r = t.equals("PREMIUM") ? new BigDecimal("0.0025") : new BigDecimal("0.005");
        return a.multiply(r).setScale(2, RoundingMode.HALF_DOWN).max(t.equals("PREMIUM")?new BigDecimal("0.10"):new BigDecimal("0.20"));
    }

    String ok(String[] f, BigDecimal fee, String cur, BigDecimal amt) {
        s.txSeq++;
        String id = "TX-" + String.format("%06d", s.txSeq);
        BankState.Transaction t = new BankState.Transaction();
        t.id = id; t.type = f[0]; t.date = f[1]; t.amount = amt; t.fee = fee;
        s.txs.put(id, t);
        s.audit.add(String.format("%03d  %s %s OK %s", ++s.auditSeq, f[0], f[1], id));
        return "OK " + id + " fee=" + String.format("%.2f", fee) + " " + cur;
    }

    String reject(String[] f, String code, String msg) {
        s.audit.add(String.format("%03d  %s %s REJECTED %s", ++s.auditSeq, f[0], f[1], code));
        return "REJECTED " + code + ": " + msg;
    }
}
